use semio_framework_test_fixtures::fixture_text;
use super::*;
use crate::{DslValue,Number,native_decoding::owned::{NativeFlatRecord,NativeRecordField},retirement::controlled::ControlledRetirement,shared_issuance::SealedShared};
#[derive(crate::RetireOwned)]#[value(crate="crate")]struct Row{value:SealedShared<String>}
impl NativeFlatRecord<1,0> for Row{
 const TEXT_FIELDS:[NativeRecordField;1]=[NativeRecordField{name:"value",ordinal:0}];const NUMBER_FIELDS:[NativeRecordField;0]=[];
 fn validation_demand(_:[&str;1],_:[Number;0])->RetirementDemand{fixed(0)}
 fn validate_parts(_:[&str;1],_:[Number;0])->Result<(),ValueError>{Ok(())}
 fn from_parts([value]:[SealedShared<String>;1],_:[Number;0])->Self{Self{value}}
}
crate::native_flat_record_receive!(Row,1,0);
fn funded(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096.max(d.copy_bytes),maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn input()->RetainedCloneSource<DslValue>{let a=RetainedCloneSource::<DslValue>::owned_constructor_demand::<()>();RetainedCloneSource::admit_owned(DslValue::Object(vec![("value".into(),DslValue::String("Original receiving owner🧱".into()))]),(),funded(RetirementDemand{copy_bytes:RetainedCloneSource::<DslValue>::constructor_copy_bytes(),capacity_bytes:a.capacity_bytes,depth:a.depth,..Default::default()})).unwrap_or_else(|_|panic!("original input admission")).0}
fn drain<T:RetireOwned>(value:T){let mut close=ControlledRetirement::new(value).unwrap_or_else(|_|panic!("original receiving typed close unsupported"));for _ in 0..10000{if close.terminal_is_empty(){return;}let g=funded(close.next_demand(4096).unwrap());assert!(close.step(g).unwrap().progress().fits(g));}panic!("original receiving typed close stalled");}
#[test]
fn native_receiving_original_keeps_cancellation_and_denied_transfers_owned(){
 type Owner=NativeReceivingOriginal<DslValue,Row>;let law:serde_json::Value=serde_json::from_str(fixture_text!("../../🧳️original/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();assert_eq!(law["closeOrder"],serde_json::json!(["receiver","output","original-source","frame"]));let mut finished=0;
 for cut in 0..128{let source=input();let source_pointer=std::ptr::from_ref(source.borrow().get());let(r,p)=<Row as NativeReceive<DslValue>>::begin_receive(funded(<Row as NativeReceive<DslValue>>::receive_birth_demand())).unwrap();assert!(p.copied_bytes>0);let birth=Owner::constructor_demand();let mut denied=funded(birth);denied.maximum_copy_bytes=birth.copy_bytes-1;let(error,source,r)=Owner::admit_parts(source,r,denied).err().unwrap();assert_eq!(error.kind,ValueRefusalKind::InvariantViolated);assert_eq!(std::ptr::from_ref(source.borrow().get()),source_pointer);let(mut owner,p)=Owner::admit_parts(source,r,funded(birth)).unwrap_or_else(|_|panic!("original receiving funded admission"));assert!(p.fits(funded(birth)));let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);let mut construction=crate::native_decoding::owned::OriginalConstructionFixture;let mut turns=0;
  while turns<cut&&!owner.output_ready(){let d=owner.demands(4096).unwrap();let g=funded(d);for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}let(step,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||super::super::list_tests::receive(&mut control,denied,|control|owner.advance(control,4096,denied)).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(owner.demands(4096).unwrap(),d);}let(step,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||super::super::list_tests::receive(&mut control,g,|control|owner.advance(control,4096,g)).unwrap());let p=step.progress();assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert_eq!(std::ptr::from_ref(owner.borrow_input().unwrap().get()),source_pointer);turns+=1;}
  if owner.output_ready(){finished=turns;let d=owner.take_demand().unwrap();let mut denied=funded(d);denied.maximum_copy_bytes=d.copy_bytes-1;assert!(owner.take(denied).unwrap().is_none());assert!(owner.output_ready());if cut%2==0{let(row,p)=owner.take(funded(d)).unwrap().unwrap();assert!(p.fits(funded(d)));assert_eq!(row.value.as_str(),"Original receiving owner🧱");drain(row);}}
  owner.begin_close();for _ in 0..10000{if owner.terminal_is_empty(){break;}if owner.receiver.is_some(){assert!(owner.original.as_ref().unwrap().try_borrow().is_ok());}else if owner.original.is_some(){assert!(owner.receiver.is_none());}let d=owner.close_demands(4096).unwrap();let g=funded(d);for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}let(step,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||owner.close_step(denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(owner.close_demands(4096).unwrap(),d);}let(step,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||owner.close_step(g).unwrap());let p=step.progress();assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));}assert!(owner.terminal_is_empty());if finished>0&&cut>finished{break;}
 }assert!(finished>0);eprintln!("[DEBUG] original native receiving {finished} turns, actual source/receiver/output custody settled at every prefix");
}
#[test]
fn native_receiving_original_shell_requires_funded_input_and_receiver_custody(){
 type Owner=NativeReceivingOriginal<DslValue,Row>;let d=Owner::shell_demand();let mut denied=funded(d);denied.maximum_copy_bytes=d.copy_bytes-1;assert!(Owner::begin_shell(denied).is_err());let(mut owner,p)=Owner::begin_shell(funded(d)).unwrap();assert!(p.fits(funded(d)));let mut source=Some(input());let original=std::ptr::from_ref(source.as_ref().unwrap().borrow().get());let d=owner.original_capture_demand().unwrap();let mut denied=funded(d);denied.maximum_copy_bytes=d.copy_bytes-1;assert_eq!(owner.admit_original(&mut source,denied).unwrap(),Default::default());assert!(source.is_some());assert!(owner.original.is_none());assert!(owner.admit_original(&mut source,funded(d)).unwrap().fits(funded(d)));assert!(source.is_none());assert_eq!(std::ptr::from_ref(owner.borrow_input().unwrap().get()),original);let d=owner.receiver_birth_demand().unwrap();let mut denied=funded(d);denied.maximum_copy_bytes=d.copy_bytes-1;assert_eq!(owner.begin_receiver(denied).unwrap(),Default::default());assert!(owner.receiver.is_none());let p=owner.begin_receiver(funded(d)).unwrap();assert!(p.fits(funded(d)));assert!(owner.receiver.is_some());assert_eq!(std::ptr::from_ref(owner.borrow_input().unwrap().get()),original);drain(owner);
 eprintln!("[DEBUG] funded empty receiving shell captures input before required receiver birth and typed cancellation");
}
